function putOn(item, look, wear) {
  if (item.kind === 'rocket') { if (itemLayer(item) === 'pattern') wear.pattern = item.pattern; else wear.paint = item.paint; return wear; }
  var o = item.faces[look];
  if (!wear.face[look]) wear.face[look] = {};
